-- Pre-Phase-3 audit resolutions (docs/contract/RESOLUTIONS.md, 43 schema changes) in one migration.
-- Generated by drizzle-kit, then reordered by hand so that every conversion of existing rows runs BEFORE the
-- constraint that needs it. Sections follow the owning module; each names the resolution it implements.
-- A CHECK, NOT NULL or unique index added to a table that holds a row it forbids makes this migration fail loudly (the
-- migration runs in one transaction, so nothing is half applied). The tables are empty before Phase 3.

-- ===== identity: auth_tokens (identity-platform-2) =====
ALTER TABLE "auth_tokens" ADD CONSTRAINT "auth_tokens_purpose_check" CHECK ("auth_tokens"."purpose" in ('invite', 'reset', 'verify_email', 'magic_link'));--> statement-breakpoint

-- ===== platform: audit_logs (identity-platform-7) =====
ALTER TABLE "audit_logs" ADD COLUMN "actor_name" text DEFAULT '' NOT NULL;--> statement-breakpoint
-- The table is append-only (trigger of migration 0001): lift the trigger for the one backfill, then restore it.
ALTER TABLE "audit_logs" DISABLE TRIGGER "audit_logs_append_only";--> statement-breakpoint
UPDATE "audit_logs" a SET "actor_name" = s."name" FROM "staff_users" s WHERE a."actor_type" = 'staff' AND a."actor_id" = s."id";--> statement-breakpoint
UPDATE "audit_logs" a SET "actor_name" = c."name" FROM "clients" c WHERE a."actor_type" = 'client' AND a."actor_id" = c."id";--> statement-breakpoint
ALTER TABLE "audit_logs" ENABLE TRIGGER "audit_logs_append_only";--> statement-breakpoint
ALTER TABLE "audit_logs" ADD CONSTRAINT "audit_logs_actor_type_check" CHECK ("audit_logs"."actor_type" in ('staff', 'client', 'customer', 'system'));--> statement-breakpoint

-- ===== platform: notifications (identity-platform-11) =====
UPDATE "notifications" SET "recipient_type" = 'client' WHERE "recipient_type" = 'merchant';--> statement-breakpoint
ALTER TABLE "notifications" ADD CONSTRAINT "notifications_recipient_type_check" CHECK ("notifications"."recipient_type" in ('staff', 'client', 'customer'));--> statement-breakpoint

-- ===== money: ledger_transactions (money-1, money-6) =====
ALTER TABLE "ledger_transactions" DROP CONSTRAINT "ledger_transactions_ref_type_check";--> statement-breakpoint
ALTER TABLE "ledger_transactions" ADD CONSTRAINT "ledger_transactions_ref_type_check" CHECK ("ledger_transactions"."ref_type" in ('order', 'payment', 'invoice', 'refund', 'dispute', 'accrual', 'supplier', 'client', 'system'));--> statement-breakpoint
-- The table is append-only, so a null ref_id cannot be backfilled: refuse to continue if one exists.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM "ledger_transactions" WHERE "ref_id" IS NULL) THEN
    RAISE EXCEPTION 'ledger_transactions has rows with a null ref_id; they are append-only and cannot be backfilled (RESOLUTIONS money-6)';
  END IF;
END
$$;--> statement-breakpoint
ALTER TABLE "ledger_transactions" ALTER COLUMN "ref_id" SET DEFAULT 0;--> statement-breakpoint
ALTER TABLE "ledger_transactions" ALTER COLUMN "ref_id" SET NOT NULL;--> statement-breakpoint
ALTER TABLE "ledger_transactions" ADD CONSTRAINT "ledger_transactions_ref_id_check" CHECK ("ledger_transactions"."ref_id" > 0 or "ledger_transactions"."ref_type" = 'system');--> statement-breakpoint

