-- ===== catalog: services (catalog-1, 2, 3, 9, 13) =====
-- catalog-2: price_mode and duplicate_rule get their defaults and closed lists.
UPDATE "services" SET "price_mode" = 'fixed' WHERE "price_mode" <> 'fixed';--> statement-breakpoint
UPDATE "services" SET "duplicate_rule" = 'block_open' WHERE "duplicate_rule" NOT IN ('allow', 'block_open');--> statement-breakpoint
ALTER TABLE "services" ALTER COLUMN "price_mode" SET DEFAULT 'fixed';--> statement-breakpoint
ALTER TABLE "services" ALTER COLUMN "duplicate_rule" SET DEFAULT 'block_open';--> statement-breakpoint
ALTER TABLE "services" ADD CONSTRAINT "services_price_mode_check" CHECK ("services"."price_mode" in ('fixed'));--> statement-breakpoint
ALTER TABLE "services" ADD CONSTRAINT "services_duplicate_rule_check" CHECK ("services"."duplicate_rule" in ('allow', 'block_open'));--> statement-breakpoint
-- catalog-9: base_price is required and positive; a missing or zero price becomes cost plus 6 % (at least 0.02).
UPDATE "services" SET "base_price" = round("cost" + greatest(round("cost" * 0.06, 2), 0.02), 2) WHERE "base_price" IS NULL OR "base_price" <= 0;--> statement-breakpoint
ALTER TABLE "services" ALTER COLUMN "base_price" SET NOT NULL;--> statement-breakpoint
ALTER TABLE "services" DROP CONSTRAINT "services_prices_check";--> statement-breakpoint
ALTER TABLE "services" ADD CONSTRAINT "services_prices_check" CHECK ("services"."cost" >= 0 and "services"."base_price" > 0);--> statement-breakpoint
-- catalog-1: effective_cost is the larger of the service cost and the synced cost of its first active supplier link.
ALTER TABLE "services" ADD COLUMN "effective_cost" numeric(18, 4) DEFAULT '0' NOT NULL;--> statement-breakpoint
UPDATE "services" s SET "effective_cost" = greatest(s."cost", coalesce((SELECT ss."credit" * sp."credit_rate" FROM "service_supplier_links" l JOIN "supplier_services" ss ON ss."id" = l."supplier_service_id" JOIN "suppliers" sp ON sp."id" = ss."supplier_id" WHERE l."service_id" = s."id" AND l."is_active" ORDER BY l."priority", l."id" LIMIT 1), 0));--> statement-breakpoint
ALTER TABLE "services" ADD CONSTRAINT "services_effective_cost_check" CHECK ("services"."effective_cost" >= "services"."cost");--> statement-breakpoint
CREATE INDEX "services_effective_cost_idx" ON "services" USING btree ("effective_cost");--> statement-breakpoint
-- catalog-3: archive instead of delete; an archived service gives its code back.
ALTER TABLE "services" ADD COLUMN "archived_at" timestamp (3) with time zone;--> statement-breakpoint
ALTER TABLE "services" ADD CONSTRAINT "services_archived_check" CHECK ("services"."archived_at" is null or "services"."status" = 'disabled');--> statement-breakpoint
DROP INDEX "services_code_uq";--> statement-breakpoint
CREATE UNIQUE INDEX "services_code_uq" ON "services" USING btree (lower("code")) WHERE "services"."archived_at" is null;--> statement-breakpoint
CREATE INDEX "services_live_type_status_idx" ON "services" USING btree ("type","status") WHERE "services"."archived_at" is null;--> statement-breakpoint
-- catalog-13: a service has the type of its category, enforced by a composite foreign key (the single-column one is
-- replaced: the composite covers it).
ALTER TABLE "service_categories" ADD CONSTRAINT "service_categories_id_type_uq" UNIQUE("id","type");--> statement-breakpoint
UPDATE "services" s SET "type" = c."type" FROM "service_categories" c WHERE c."id" = s."category_id" AND s."type" <> c."type";--> statement-breakpoint
ALTER TABLE "services" DROP CONSTRAINT "services_category_id_service_categories_id_fk";--> statement-breakpoint
ALTER TABLE "services" ADD CONSTRAINT "services_category_type_fk" FOREIGN KEY ("category_id","type") REFERENCES "public"."service_categories"("id","type") ON DELETE restrict ON UPDATE cascade;--> statement-breakpoint
-- The composite key needs a full index that starts with (category_id, type); it replaces the one on category_id alone.
DROP INDEX "services_category_id_idx";--> statement-breakpoint
CREATE INDEX "services_category_type_idx" ON "services" USING btree ("category_id","type");--> statement-breakpoint

-- ===== catalog: inventory_codes (catalog-15) =====
CREATE SEQUENCE "public"."inventory_batch_ref_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1;--> statement-breakpoint
UPDATE "inventory_codes" SET "batch_ref" = 'B-0000' WHERE "batch_ref" IS NULL OR "batch_ref" = '';--> statement-breakpoint
-- Continue after the highest existing batch number; with no numbered batch the first nextval() returns 1.
SELECT setval('"public"."inventory_batch_ref_seq"', greatest(1, m."top"), m."top" > 0) FROM (SELECT coalesce(max(substring("batch_ref" from '^B-([0-9]+)$')::bigint), 0) AS "top" FROM "inventory_codes") m;--> statement-breakpoint
ALTER TABLE "inventory_codes" ALTER COLUMN "batch_ref" SET NOT NULL;--> statement-breakpoint
