-- ===== suppliers: supplier_api_logs (orders-suppliers-3; health-commissions-8) =====
-- The outcome is derived first, while a missing answer is still null (or 0) and a missing error still null.
ALTER TABLE "supplier_api_logs" ADD COLUMN "outcome" text DEFAULT 'ok' NOT NULL;--> statement-breakpoint
UPDATE "supplier_api_logs" SET "outcome" = CASE WHEN ("http_status" IS NULL OR "http_status" = 0) AND ("error" ILIKE '%timeout%' OR "error" ILIKE '%timed out%') THEN 'timeout' WHEN ("error" IS NOT NULL AND "error" <> '') OR "http_status" >= 400 THEN 'error' ELSE 'ok' END;--> statement-breakpoint
UPDATE "supplier_api_logs" SET "http_status" = COALESCE("http_status", 0), "duration_ms" = COALESCE("duration_ms", 0), "error" = COALESCE("error", '');--> statement-breakpoint
