ALTER TABLE "supplier_api_logs" ALTER COLUMN "error" SET NOT NULL;--> statement-breakpoint
ALTER TABLE "supplier_api_logs" ADD CONSTRAINT "supplier_api_logs_numbers_check" CHECK ("supplier_api_logs"."http_status" >= 0 and "supplier_api_logs"."duration_ms" >= 0);--> statement-breakpoint
ALTER TABLE "supplier_api_logs" ADD CONSTRAINT "supplier_api_logs_outcome_check" CHECK ("supplier_api_logs"."outcome" in ('ok', 'error', 'timeout'));--> statement-breakpoint

